class Solution {
  private int[] bit;
  private int n;

  private void update(int i, int v) {
    for (; i <= n + 1; i += i & -i) bit[i] ^= v;
  }

  private int prefix(int i) {
    int r = 0;
    for (; i > 0; i -= i & -i) r ^= bit[i];
    return r;
  }

  public List<Boolean> palindromePath(int n, int[][] edges, String s, String[] queries) {
    this.n = n;
    bit = new int[n + 3];
    int[] start = new int[n + 1];
    for (int[] e : edges) {
      start[e[0] + 1]++;
      start[e[1] + 1]++;
    }
    for (int i = 0; i < n; i++) start[i + 1] += start[i];
    int[] fill = new int[n], to = new int[2 * (n - 1)];
    for (int[] e : edges) {
      to[start[e[0]] + fill[e[0]]++] = e[1];
      to[start[e[1]] + fill[e[1]]++] = e[0];
    }
    int LOG = 1;
    while ((1 << LOG) < n) LOG++;
    int[][] up = new int[LOG + 1][n];
    int[] depth = new int[n],
        tin = new int[n],
        tout = new int[n],
        ptr = new int[n],
        stack = new int[n];
    int sp = 0, timer = 0;
    stack[sp++] = 0;
    tin[0] = ++timer;
    for (int i = 0; i < n; i++) ptr[i] = start[i];
    while (sp > 0) {
      int u = stack[sp - 1];
      if (ptr[u] < start[u + 1]) {
        int v = to[ptr[u]++];
        if (u != 0 && v == up[0][u]) continue;
        up[0][v] = u;
        depth[v] = depth[u] + 1;
        tin[v] = ++timer;
        stack[sp++] = v;
      } else {
        tout[u] = timer;
        sp--;
      }
    }
    for (int l = 1; l <= LOG; l++) for (int i = 0; i < n; i++) up[l][i] = up[l - 1][up[l - 1][i]];
    char[] chars = s.toCharArray();
    for (int i = 0; i < n; i++) {
      int mask = 1 << (chars[i] - 'a');
      update(tin[i], mask);
      update(tout[i] + 1, mask);
    }
    List<Boolean> res = new ArrayList<>();
    for (String q : queries) {
      String[] p = q.split(" ");
      if (p[0].equals("update")) {
        int u = Integer.parseInt(p[1]);
        int delta = (1 << (chars[u] - 'a')) ^ (1 << (p[2].charAt(0) - 'a'));
        chars[u] = p[2].charAt(0);
        update(tin[u], delta);
        update(tout[u] + 1, delta);
      } else {
        int u = Integer.parseInt(p[1]), v = Integer.parseInt(p[2]);
        int a = u, b = v;
        if (depth[a] < depth[b]) {
          int t = a;
          a = b;
          b = t;
        }
        for (int l = 0; l <= LOG; l++) if (((depth[a] - depth[b]) >> l & 1) != 0) a = up[l][a];
        if (a != b) {
          for (int l = LOG; l >= 0; l--) {
            if (up[l][a] != up[l][b]) {
              a = up[l][a];
              b = up[l][b];
            }
          }
          a = up[0][a];
        }
        int mask = prefix(tin[u]) ^ prefix(tin[v]) ^ (1 << (chars[a] - 'a'));
        res.add((mask & (mask - 1)) == 0);
      }
    }
    return res;
  }
}
